/* v111 -- revs 238. */
static void
npc_info_small_v5_v111_record(RsprotBuf *b, RsprotNpcRecord *r)
{
    r->dz = rsprot_gbits(b, 6);
    if (r->dz >= 32)
        r->dz -= 64;
    r->jump = rsprot_gbits(b, 1);
    r->angle = rsprot_gbits(b, 3);
    r->type = rsprot_gbits(b, 14);
    r->dx = rsprot_gbits(b, 6);
    if (r->dx >= 32)
        r->dx -= 64;
    r->extended = rsprot_gbits(b, 1);
    r->has_spawn_cycle = rsprot_gbits(b, 1);
    if (r->has_spawn_cycle)
        r->spawn_cycle = (uint32_t)rsprot_gbits(b, 32);
}

